// Arma un solo INSERT con todas las grabaciones de esta corrida.
// Se lee del nodo Fetch (no de $input) porque los nodos de Telegram
// reemplazan el json del item con la respuesta de su API y pierden
// filename/phone.
function esc(v) {
  if (v === null || v === undefined || v === '') return 'NULL';
  return "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "''") + "'";
}
function num(v) { const n = Number(v); return Number.isFinite(n) ? n : 0; }

const items = $('🔄 Fetch & Convert Stringee Recordings2').all();
if (!items.length) {
  console.log('WF10: nada que registrar en el ledger');
  return [];
}

const values = items.map(it => {
  const r = it.json;
  return '(' + [esc(r.filename), esc(r.phone), esc(r.country), num(r.duration_secs)].join(',') + ')';
}).join(',\n');

// ON DUPLICATE KEY: si por una carrera dos corridas tomaran el mismo
// archivo, la segunda no explota ni crea una fila duplicada.
const sql = `INSERT INTO wf10_sent_recordings (filename, phone, country, duration_secs)
VALUES
${values}
ON DUPLICATE KEY UPDATE sent_at = sent_at;`;

console.log(`WF10: registrando ${items.length} grabacion(es) en el ledger`);
return [{ json: { sql, n: items.length } }];

const item = $input.first().json;
const body = item.body || item;

const base64 = body.audio_base64;
const buffer = Buffer.from(base64, 'base64');

const phoneRaw = String(body.phone || '');
const phoneDigits = phoneRaw.replace(/[^0-9]/g, '');

let country = 'unknown';
if (phoneDigits.startsWith('91')) country = 'india';
else if (phoneDigits.startsWith('977')) country = 'nepal';
else if (phoneDigits.startsWith('58')) country = 'venezuela';
else if (phoneDigits.startsWith('52')) country = 'mexico';
else if (phoneDigits.startsWith('57')) country = 'colombia';

// Duración real desde el header WAV. CRM NO usa este valor como filtro;
// solamente se usa más adelante para decidir si Telegram recibe el audio.
let duration_secs = 0;
let duration_unknown = true;
try {
  if (buffer.length >= 44 && buffer.toString('ascii', 0, 4) === 'RIFF') {
    const byteRate = buffer.readUInt32LE(28);
    if (byteRate > 0) {
      duration_secs = Math.round(Math.max(0, buffer.length - 44) / byteRate);
      duration_unknown = false;
    }
  }
} catch (e) {
  duration_secs = 0;
  duration_unknown = true;
}

return [{
  json: {
    phone: body.phone,
    date: body.date,
    filename: body.filename,
    country,
    duration_secs,
    duration_unknown
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/wav',
      fileName: body.filename
    }
  }
}];

// Telegram recibe SOLO llamadas contestadas de >= 60 s.
// Este nodo corre después de la subida al CRM; el CRM no tiene filtro de duración.
const items = $('🔗 Attach Audio + Token (Asterisk)').all();

return items
  .filter(it => {
    const secs = Number(it.json.duration_secs || 0);
    return it.json.duration_unknown !== true && secs >= 60;
  })
  .map(it => ({
    json: it.json,
    binary: it.binary
  }));

// Lee grabaciones del worker Stringee.
// IMPORTANTE: aquí NO se filtra por duración.
// CRM debe recibir TODAS las llamadas contestadas; el filtro >=60 s se aplica
// únicamente en la rama de Telegram, después de subir al CRM.

// Lista de grabaciones ya procesadas con éxito por WF10 (ledger).
const yaEnviadas = new Set(
  $input.all()
    .map(i => i.json && i.json.filename)
    .filter(Boolean)
);

// Fecha de hoy en UTC (timestamp_ms viene en epoch UTC).
const hoy = new Date().toISOString().split('T')[0];

function wavDurationSecs(b64, sizeBytes) {
  try {
    const head = Buffer.from(b64.slice(0, 120), 'base64');
    if (head.length < 44) return null;
    if (head.toString('ascii', 0, 4) !== 'RIFF') return null;
    const byteRate = head.readUInt32LE(28);
    if (!byteRate) return null;
    const dataBytes = Math.max(0, (sizeBytes || head.length) - 44);
    return Math.round(dataBytes / byteRate);
  } catch (e) {
    return null;
  }
}

const listData = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://172.18.0.1:8091/recordings',
  json: true
});
const files = listData.recordings || [];

const results = [];
let skipEnviada = 0, skipVieja = 0, skipError = 0;

for (const rec of files) {
  try {
    if (yaEnviadas.has(rec.filename)) { skipEnviada++; continue; }

    const fecha = new Date(rec.timestamp_ms).toISOString().split('T')[0];
    if (fecha !== hoy) { skipVieja++; continue; }

    const dlData = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://172.18.0.1:8091/recordings/${rec.filename}`,
      json: true
    });
    if (!dlData.ok || !dlData.audio_base64) { skipError++; continue; }

    const secs = wavDurationSecs(dlData.audio_base64, rec.size_bytes);

    const digits = String(rec.phone).replace(/[^0-9]/g, '');
    let country = 'unknown';
    if (digits.startsWith('977')) country = 'nepal';
    else if (digits.startsWith('52')) country = 'mexico';
    else if (digits.startsWith('91')) country = 'india';

    results.push({
      json: {
        phone: rec.phone,
        date: fecha,
        filename: rec.filename,
        country,
        size_bytes: rec.size_bytes,
        duration_secs: secs === null ? 0 : secs,
        duration_unknown: secs === null
      },
      binary: {
        data: {
          data: dlData.audio_base64,
          mimeType: 'audio/wav',
          fileName: rec.filename
        }
      }
    });
  } catch (e) {
    skipError++;
  }
}

console.log(`WF10 Stringee: ${files.length} en worker -> ${results.length} candidatos ` +
            `| ya procesadas: ${skipEnviada} | no son de hoy: ${skipVieja} | error: ${skipError}`);

return results;

// Telegram recibe SOLO las llamadas contestadas de >=60 s.
// El CRM ya recibió la llamada antes de llegar aquí, sin importar su duración.
const items = $('🔗 Attach Audio + Token (Stringee)').all();

return items
  .filter(it => {
    const secs = Number(it.json.duration_secs || 0);
    return it.json.duration_unknown !== true && secs >= 60;
  })
  .map(it => ({
    json: it.json,
    binary: it.binary
  }));

try {
  const token = $input.item.json.accessToken;
  const lookup = $('🔍 Lookup Followup ID (Asterisk)').item.json;
  const original = $('Convert Base64 to Binary').item;
  return {
